import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cross_entropy_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void cross_entropy_forward_kernel(const float* logits, const int* targets, float* output,
                                             int batch_size, int num_classes) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        int offset = idx * num_classes;
        float max_val = -1e30f;
        // Find max for numerical stability
        for(int c = 0; c < num_classes; c++){
            float val = logits[offset + c];
            if(val > max_val){
                max_val = val;
            }
        }
        // Compute log-sum-exp
        float sum_exp = 0.0f;
        for(int c = 0; c < num_classes; c++){
            sum_exp += expf(logits[offset + c] - max_val);
        }
        float logsumexp = max_val + logf(sum_exp);
        // Compute loss for the correct class
        int target = targets[idx];
        float loss = -( logits[offset + target] - logsumexp );
        output[idx] = loss;
    }
}

torch::Tensor cross_entropy_forward_cuda(torch::Tensor logits, torch::Tensor targets) {
    TORCH_CHECK(logits.is_cuda(), "logits must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(logits.dim() == 2, "logits must be 2D (batch_size, num_classes)");
    TORCH_CHECK(targets.dim() == 1, "targets must be 1D (batch_size)");

    int batch_size = logits.size(0);
    int num_classes = logits.size(1);

    auto output = torch::zeros({batch_size}, logits.options());

    const int block_size = 256;
    const int grid_size = (batch_size + block_size - 1) / block_size;

    cross_entropy_forward_kernel<<<grid_size, block_size>>>(
        logits.data_ptr<float>(),
        targets.data_ptr<int>(),
        output.data_ptr<float>(),
        batch_size,
        num_classes
    );

    return output;
}
"""

cross_entropy_cpp_source = r"""
torch::Tensor cross_entropy_forward_cuda(torch::Tensor logits, torch::Tensor targets);
"""

cross_entropy_ext = load_inline(
    name="cross_entropy_ext",
    cpp_sources=cross_entropy_cpp_source,
    cuda_sources=cross_entropy_source,
    functions=["cross_entropy_forward_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    A model that computes Cross Entropy Loss for multi-class classification tasks using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.cross_entropy = cross_entropy_ext

    def forward(self, predictions, targets):
        # Compute partial losses for each sample.
        partial_losses = self.cross_entropy.cross_entropy_forward_cuda(predictions, targets)
        # Return mean loss over the batch.
        return partial_losses.mean()
